<?php

namespace App\Notifications;

use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Notifications\Messages\MailMessage;
use Illuminate\Notifications\Notification;

/**
 * Links to the Next.js frontend's /verify-email page with a single opaque
 * token query param — not Laravel's default signed backend route, since
 * the frontend already ships against that simpler contract (see
 * docs/auth-api-contract.md). The token itself is generated by
 * EmailVerificationService; this class only knows how to deliver it.
 */
class VerifyEmailNotification extends Notification implements ShouldQueue
{
    use Queueable;

    public function __construct(private readonly string $token) {}

    public function via(object $notifiable): array
    {
        return ['mail'];
    }

    public function toMail(object $notifiable): MailMessage
    {
        $url = rtrim(config('app.frontend_url'), '/').'/verify-email?token='.$this->token;

        return (new MailMessage)
            ->subject('Verify your DAC Accounting email address')
            ->line('Please click the button below to verify your email address.')
            ->action('Verify Email Address', $url)
            ->line('This link will expire, and this email was sent because an account was created with this address.');
    }
}
